/* Explicit local-only, FULL 2,512-event preview. User selects a private
 * export generated by the existing pinned 2,512-event pipeline. This module
 * never fetches, uploads, caches or publishes the selected event file. */
(function(g){
'use strict';
const PUBLIC=typeof module!=='undefined'&&module.exports
 ?require('./public_event_catalog.js'):g.UmaPublicEventCatalog;
const PIN='6e38b54af4fad397ff4491e63007a90705a4fe67';
const KIND='umasupport-phase2-private-local-catalog';
const REQUIRED_CARDS=563,REQUIRED_EVENTS=2512;
const fail=x=>{throw Error('非公開2,512件ローカル読込: '+x);};
const obj=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
const shaPattern=/^[a-f0-9]{64}$/;
function hex(bytes){return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
async function digest(text){
 const subtle=g.crypto?.subtle||
  (typeof module!=='undefined'&&module.exports
   ?require('node:crypto').webcrypto.subtle:null);
 if(!subtle)fail('暗号学的ハッシュ検証に対応していない環境です');
 return hex(await subtle.digest('SHA-256',new TextEncoder().encode(text)));
}
async function verifyBundle(raw,model,skillText){
 if(typeof raw!=='string'||raw.length<100||raw.length>30000000)
  fail('ローカルファイルのサイズまたは形式が不正');
 let packet;
 try{packet=JSON.parse(raw.replace(/^\uFEFF/,''));}
 catch{fail('JSONを解析できません');}
 if(!obj(packet)||Object.keys(packet).some(k=>![
   'schemaVersion','dataKind','sourceRevision','publicationApproved',
   'reviewedEventsPublished','noAutomaticRuntimeAdoption',
   'sourceNarrativeOrChoiceProseIncluded','fullEventRewardOrChainCoverageVerified',
   'sourceDatasetPublished','catalogSha256','summary','catalog'].includes(k))||
   packet.schemaVersion!==1||packet.dataKind!==KIND||
   packet.sourceRevision!==PIN||packet.publicationApproved!==false||
   packet.reviewedEventsPublished!==0||
   packet.noAutomaticRuntimeAdoption!==true||
   packet.sourceNarrativeOrChoiceProseIncluded!==false||
   packet.fullEventRewardOrChainCoverageVerified!==false||
   packet.sourceDatasetPublished!==false||
   !obj(packet.catalog)||packet.catalog.schemaVersion!==1||
   !Array.isArray(packet.catalog.cards)||!obj(packet.summary)||
   packet.summary.cards!==REQUIRED_CARDS||
   packet.summary.events!==REQUIRED_EVENTS||
   !shaPattern.test(packet.catalogSha256||''))
  fail('出典版・非公開フラグ・2512件母数の契約が不正');
 if(!model?.meta||model.meta.runtimeSources?.events?.mode!=='reviewed'||
    model.meta.reviewedEventRecords!==0)
  fail('公開イベントJSONが正常かつ空でなければ、ローカル候補を適用しません');
 if(typeof skillText!=='string'||!skillText.trim())fail('検証済みスキル辞書が必要');
 if(!Array.isArray(model.cards)||model.cards.length<REQUIRED_CARDS)
  fail('最新のサポートカード名簿が不完全');
 const ids=new Set();
 let count=0;
 for(const card of packet.catalog.cards){
  if(!obj(card)||!/^\d{5}$/.test(card.cardId)||ids.has(card.cardId)||
     !model.cardById[card.cardId]||card.coverageStatus!=='partial'||
     !Array.isArray(card.events))fail('カードID・収録範囲の対応が不正');
  ids.add(card.cardId);count+=card.events.length;
 }
 if(ids.size!==REQUIRED_CARDS||count!==REQUIRED_EVENTS)
  fail('カード件数またはイベント件数が固定出典と相違');
 const actual=await digest(JSON.stringify(packet.catalog));
 if(actual!==packet.catalogSha256)
  fail('カタログのSHA-256が一致しません');
 // Exact production ID/name/choice/outcome/schema preflight on all records.
 const checked=PUBLIC.preflight(model,packet.catalog,{skillText,fullRegistry:false});
 if(checked.summary.eventsWithRecords!==REQUIRED_EVENTS||
    checked.summary.cardsWithRecords!==REQUIRED_CARDS)
  fail('本番スキーマ検証でイベント／カードの件数が相違');
 return {catalog:packet.catalog,catalogSha256:actual,
  cards:checked.summary.cardsWithRecords,events:checked.summary.eventsWithRecords};
}
async function activate(model,{text,skillText}={}){
 const checked=await verifyBundle(text,model,skillText);
 // attach validates again before changing any model state.
 const summary=PUBLIC.attach(model,checked.catalog,{skillText,fullRegistry:false});
 if(summary.eventsWithRecords!==REQUIRED_EVENTS)
  fail('検証後に実行モデルのイベント数が変化');
 // The production loader's "reviewed-partial" name is not evidence of
 // human publication. Explicitly mark every private local route as preview.
 model.meta.reviewedEventRecords=0;
 model.meta.reviewedEventCards=0;
 model.meta.eventStatus='preview-only';
 model.meta.previewEvents={
  cardId:'local',records:REQUIRED_EVENTS,cards:REQUIRED_CARDS,
  source:'user-selected private 2512-event bundle, NOT published',
  catalogSha256:checked.catalogSha256,excluded:null,
  sourcePin:PIN,publicationApproved:false};
 model.meta.runtimeSources.events={mode:'preview',url:null,previewUrl:null,
  localOnly:true,catalogSha256:checked.catalogSha256};
 return {cards:REQUIRED_CARDS,records:REQUIRED_EVENTS,
  catalogSha256:checked.catalogSha256,publicationApproved:false};
}
const api={KIND,PIN,verifyBundle,activate,digest};
if(typeof module!=='undefined'&&module.exports)module.exports=api;
g.UmaPrivateLocalEventPreview=api;
})(typeof globalThis!=='undefined'?globalThis:this);
